def count_passed(scores):
    count = 0
    for score in scores:
        if score >= 80:
            count = count + 1
    return count

print(count_passed([80, 65, 80]))
print(count_passed([]))

def count_at_least(scores, cutoff):
    count = 0
    for score in scores:
        if score >= cutoff:
            count += 1
    return count

print(count_at_least([], 80))
print(count_at_least([79, 80, 80], 80))
print(count_at_least([0, 100], 100))

def count_in_range(values, low, high):
    count = 0
    for value in values:
        if low <= value and value <= high:
            count += 1
    return count

print(count_in_range([], -1, 1))
print(count_in_range([-1, 0, 1, 1, 2], 0, 1))
print(count_in_range([2, 2, 3], 2, 2))

def pass_summary(scores):
    passed = 0
    failed = 0
    for score in scores:
        if score >= 80:
            passed += 1
        else:
            failed += 1
    return passed, failed

print(pass_summary([]))
print(pass_summary([79, 80, 100]))
print(pass_summary([80, 80]))
